-- Share cartons by recognized city, marketplace and confirmed shop; do not change business records.
CREATE VIEW av2_supply_city_scopes AS SELECT id,market,store,destination,(CASE WHEN (((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Пп][Бб][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт] [Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт]-[Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт][Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт] [Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт]-[Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт][Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Пп][Ии][Тт][Ее][Рр][^A-Za-zА-Яа-яЁё0-9]*') + ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Мм][Оо][Сс][Кк][Вв][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Мм][Оо][Сс][Кк][Вв][Ыы][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Мм][Сс][Кк][^A-Za-zА-Яа-яЁё0-9]*') + ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Ее][Кк][Бб][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Ее][Кк][Аа][Тт][Ее][Рр][Ии][Нн][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*') + ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Нн][Оо][Вв][Оо][Сс][Ии][Бб][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Нн][Оо][Вв][Оо][Сс][Ии][Бб][Ии][Рр][Сс][Кк][^A-Za-zА-Яа-яЁё0-9]*') + ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Аа][Зз][Аа][Нн][Ьь][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Аа][Зз][Аа][Нн][Ии][^A-Za-zА-Яа-яЁё0-9]*') + ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Рр][Оо][Сс][Тт][Оо][Вв][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Рр][Оо][Сс][Тт][Оо][Вв][Аа][^A-Za-zА-Яа-яЁё0-9]*') + ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Оо][Сс][Тт][Рр][Оо][Мм][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Оо][Сс][Тт][Рр][Оо][Мм][Ыы][^A-Za-zА-Яа-яЁё0-9]*'))=1 THEN CASE WHEN ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Пп][Бб][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт] [Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт]-[Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт][Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт] [Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт]-[Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Сс][Аа][Нн][Кк][Тт][Пп][Ее][Тт][Ее][Рр][Бб][Уу][Рр][Гг][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Пп][Ии][Тт][Ее][Рр][^A-Za-zА-Яа-яЁё0-9]*') THEN 'SPB' WHEN ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Мм][Оо][Сс][Кк][Вв][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Мм][Оо][Сс][Кк][Вв][Ыы][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Мм][Сс][Кк][^A-Za-zА-Яа-яЁё0-9]*') THEN 'MOSCOW' WHEN ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Ее][Кк][Бб][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Ее][Кк][Аа][Тт][Ее][Рр][Ии][Нн][Бб][Уу][Рр][Гг][^A-Za-zА-Яа-яЁё0-9]*') THEN 'EKATERINBURG' WHEN ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Нн][Оо][Вв][Оо][Сс][Ии][Бб][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Нн][Оо][Вв][Оо][Сс][Ии][Бб][Ии][Рр][Сс][Кк][^A-Za-zА-Яа-яЁё0-9]*') THEN 'NOVOSIBIRSK' WHEN ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Аа][Зз][Аа][Нн][Ьь][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Аа][Зз][Аа][Нн][Ии][^A-Za-zА-Яа-яЁё0-9]*') THEN 'KAZAN' WHEN ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Рр][Оо][Сс][Тт][Оо][Вв][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Рр][Оо][Сс][Тт][Оо][Вв][Аа][^A-Za-zА-Яа-яЁё0-9]*') THEN 'ROSTOV' WHEN ((' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Оо][Сс][Тт][Рр][Оо][Мм][Аа][^A-Za-zА-Яа-яЁё0-9]*' OR (' '||destination||' ') GLOB '*[^A-Za-zА-Яа-яЁё0-9][Кк][Оо][Сс][Тт][Рр][Оо][Мм][Ыы][^A-Za-zА-Яа-яЁё0-9]*') THEN 'KOSTROMA' END END) city_key FROM av2_supplies;
